<?php
admin_required();$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'';$id=(int)($_POST['id']??0);if($act==='delete'){try{db()->prepare('DELETE FROM routes WHERE id=?')->execute([$id]);flash('Route removed.');}catch(Throwable $e){flash('Route is in use by a schedule and cannot be deleted.','error');}header('Location: ?page=routes');exit;}if(in_array($act,['create','update'],true)){$name=trim((string)($_POST['name']??''));$code=strtoupper(trim((string)($_POST['train_code']??'')));$a=(int)($_POST['from_station']??0);$b=(int)($_POST['to_station']??0);$fare=filter_var($_POST['fare']??null,FILTER_VALIDATE_FLOAT);if(mb_strlen($name)<3||mb_strlen($name)>100||!preg_match('/^[A-Z0-9-]{2,12}$/',$code)||!$a||!$b||$a===$b||$fare===false||$fare<1||$fare>2000){flash('Enter a valid route, train code, two different stations and fare.','error');}else{if($act==='create')db()->prepare('INSERT INTO routes(name,train_code,from_station_id,to_station_id,base_fare) VALUES(?,?,?,?,?)')->execute([$name,$code,$a,$b,$fare]);else db()->prepare('UPDATE routes SET name=?,train_code=?,from_station_id=?,to_station_id=?,base_fare=? WHERE id=?')->execute([$name,$code,$a,$b,$fare,$id]);flash('Route saved.');header('Location: ?page=routes');exit;}}}
$stations=db()->query('SELECT id,name FROM stations ORDER BY name')->fetchAll();$routes=db()->query('SELECT r.*,a.name origin,b.name destination FROM routes r JOIN stations a ON a.id=r.from_station_id JOIN stations b ON b.id=r.to_station_id ORDER BY r.name')->fetchAll();
?>
<section class="page-banner"><div class="container admin-banner"><div><p class="eyebrow">STAFF WORKSPACE</p><h1>Route <em>management.</em></h1><p>Create, update and remove sample routes and fares.</p></div><a class="button secondary" href="?page=admin">← Operations</a></div></section><section class="container content-section"><div class="route-admin-grid"><form class="form-card" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="create"><p class="eyebrow">CREATE A ROUTE</p><h2>New connection</h2><label>Route name<input name="name" maxlength="100" required placeholder="Kuala Lumpur — Ipoh"></label><label>Train code<input name="train_code" maxlength="12" required placeholder="ETS 9212"></label><div class="form-row"><label>From<select name="from_station" required><?php foreach($stations as $s): ?><option value="<?= (int)$s['id'] ?>"><?= h($s['name']) ?></option><?php endforeach; ?></select></label><label>To<select name="to_station" required><?php foreach($stations as $s): ?><option value="<?= (int)$s['id'] ?>"><?= h($s['name']) ?></option><?php endforeach; ?></select></label></div><label>Base fare (RM)<input type="number" name="fare" min="1" max="2000" step="0.01" required></label><button class="button primary">Create route +</button></form><div class="route-list"><p class="eyebrow">CURRENT CONNECTIONS · <?= count($routes) ?></p><?php foreach($routes as $r): ?><details class="route-item"><summary><span><strong><?= h($r['train_code']) ?></strong><small><?= h($r['origin']) ?> → <?= h($r['destination']) ?></small></span><b><?= money((float)$r['base_fare']) ?></b></summary><form method="post" class="route-edit"><?= csrf_field() ?><input type="hidden" name="action" value="update"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label>Route name<input name="name" value="<?= h($r['name']) ?>" required></label><div class="form-row"><label>Train code<input name="train_code" value="<?= h($r['train_code']) ?>" required></label><label>Fare (RM)<input type="number" name="fare" min="1" max="2000" step=".01" value="<?= h($r['base_fare']) ?>" required></label></div><div class="form-row"><label>From<select name="from_station"><?php foreach($stations as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $s['id']==$r['from_station_id']?'selected':'' ?>><?= h($s['name']) ?></option><?php endforeach; ?></select></label><label>To<select name="to_station"><?php foreach($stations as $s): ?><option value="<?= (int)$s['id'] ?>" <?= $s['id']==$r['to_station_id']?'selected':'' ?>><?= h($s['name']) ?></option><?php endforeach; ?></select></label></div><button class="button secondary small">Save changes</button></form><form method="post" class="delete-route"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="text-link danger-text" data-confirm="Delete this route? It will fail if schedules use it.">Delete route</button></form></details><?php endforeach; ?></div></div></section>
